from pathlib import Path
import tempfile, subprocess, re
root=Path.cwd()
with tempfile.TemporaryDirectory(dir='/tmp/opencode') as d:
    d=Path(d)
    (d/'assets').symlink_to(root/'assets', target_is_directory=True)
    html=(root/'index.html').read_text()
    test='''<script>
(()=>{
  const mark=(ok,msg)=>document.body.setAttribute('data-flow-test',(ok?'PASS: ':'FAIL: ')+msg);
  try {
    document.getElementById('newGame').click();
    const scenario=document.getElementById('scenario');
    if(!scenario.classList.contains('active')) throw Error('New Game did not open scenario screen');
    document.getElementById('beginningScenario').click();
    const panel=document.getElementById('characterPanel');
    if(panel.hidden) throw Error('character panel stayed hidden');
    if(!panel.innerText.includes('Lux Osborn') || !panel.innerText.includes('responsibility must be earned')) throw Error('biography content missing');
    if(document.getElementById('startScenario').innerText.trim()!=='Next') throw Error('Next button missing');
    document.getElementById('startScenario').click();
    if(!document.getElementById('game').classList.contains('active')) throw Error('Next did not begin game');
    mark(true,'scenario -> Lux Osborn -> Next -> game');
  } catch(e) { mark(false,e.message); }
})();
</script>'''
    (d/'index.html').write_text(html.replace('</body>',test+'\n</body>'))
    p=subprocess.run(['chromium','--headless','--no-sandbox','--disable-gpu','--hide-scrollbars','--dump-dom',f'file://{d}/index.html'],capture_output=True,text=True,timeout=60)
    m=re.search(r'data-flow-test="([^"]+)"',p.stdout)
    print(m.group(1) if m else 'Browser test marker missing')
    if not m or not m.group(1).startswith('PASS'):
        print(p.stderr[-1500:])
        raise SystemExit(1)
